:root { color-scheme: light; --ink: #24352d; --muted: #65746b; --cream: #fbf8ef; --green: #3b7657; --lime: #c7e58a; --line: #e3e7dc; }
* { box-sizing: border-box; }
body { margin: 0; min-height: 100vh; display: grid; place-items: center; padding: 28px 16px; background-color: #eaf0df; background-image: linear-gradient(45deg, #dce8d1 25%, transparent 25%), linear-gradient(-45deg, #dce8d1 25%, transparent 25%), linear-gradient(45deg, transparent 75%, #dce8d1 75%), linear-gradient(-45deg, transparent 75%, #dce8d1 75%); background-size: 32px 32px; background-position: 0 0, 0 16px, 16px -16px, -16px 0; color: var(--ink); font: 16px/1.5 system-ui, sans-serif; }
.card { width: min(100%, 760px); padding: clamp(24px, 5vw, 48px); border: 2px solid var(--ink); border-radius: 18px; background: var(--cream); box-shadow: 8px 8px 0 var(--ink); }
.header { text-align: center; }
.pixel-mark { margin: 0 auto 12px; width: 48px; height: 48px; display: grid; place-items: center; border: 2px solid var(--ink); border-radius: 12px; background: var(--lime); font-size: 30px; line-height: 1; }
.eyebrow, footer { color: var(--green); font-size: 13px; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 4px 0 8px; font-size: clamp(27px, 6vw, 38px); line-height: 1.15; letter-spacing: -.04em; }
.intro { max-width: 480px; margin: 0 auto; color: var(--muted); }
.form { margin-top: 30px; padding: 24px; border: 1px solid var(--line); border-radius: 14px; background: #fffdf7; }
.fields { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }
.field label { display: block; margin-bottom: 7px; font-weight: 700; }
.input-wrap { display: flex; align-items: center; gap: 8px; min-height: 50px; padding: 0 13px; border: 1.5px solid #bbc8b7; border-radius: 9px; background: white; color: var(--muted); }
.input-wrap:focus-within { border-color: var(--green); box-shadow: 0 0 0 3px #c7e58a88; }
input { width: 100%; min-width: 0; padding: 10px 0; border: 0; outline: 0; background: transparent; color: var(--ink); font: inherit; }
button { width: 100%; margin-top: 20px; padding: 14px 18px; border: 2px solid var(--ink); border-radius: 10px; background: var(--green); color: white; font: inherit; font-weight: 800; cursor: pointer; transition: transform .12s, background .12s, box-shadow .12s; }
button:hover { background: #2f6448; box-shadow: 0 4px 0 var(--ink); transform: translateY(-2px); }
button:active { box-shadow: none; transform: translateY(2px); }
button:focus-visible { outline: 3px solid var(--lime); outline-offset: 3px; }
.note, .table-note { margin: 12px 0 0; color: var(--muted); font-size: 14px; text-align: center; }
.results { margin-top: 28px; }
[hidden] { display: none !important; }
.summary { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 28px; }
.stat { padding: 18px; border: 1px solid var(--line); border-radius: 12px; background: #eef4e7; }
.stat-label { display: block; color: var(--muted); font-size: 14px; font-weight: 700; }
.stat-value { display: block; margin-top: 3px; font-size: clamp(22px, 5vw, 30px); font-weight: 850; letter-spacing: -.03em; }
.table-heading { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 10px; }
h2 { margin: 0; font-size: 19px; }
.badge { flex: none; padding: 4px 10px; border-radius: 99px; background: var(--lime); font-size: 13px; font-weight: 800; }
.table-scroll { max-height: 360px; overflow: auto; border: 1px solid var(--line); border-radius: 10px; background: white; }
.table-scroll:focus-visible { outline: 3px solid var(--green); outline-offset: 2px; }
table { width: 100%; border-collapse: collapse; text-align: right; font-variant-numeric: tabular-nums; }
th, td { padding: 11px 14px; border-bottom: 1px solid var(--line); white-space: nowrap; }
th { position: sticky; top: 0; background: #eef4e7; font-size: 14px; }
th:first-child, td:first-child { text-align: left; }
tbody tr:last-child td { border-bottom: 0; }
tbody tr.goal-row { background: #f1f7e6; font-weight: 800; }
.message { min-height: 24px; margin: 12px 0 0; color: #a54232; font-weight: 650; }
footer { margin-top: 22px; text-align: center; font-size: 11px; }
@media (max-width: 600px) { .fields { grid-template-columns: 1fr; gap: 12px; } .form { padding: 18px; } .card { box-shadow: 5px 5px 0 var(--ink); } }
@media (max-width: 400px) { body { padding: 14px 10px; } .card { padding: 22px 16px; } th, td { padding: 10px 9px; font-size: 14px; } }

const form = document.getElementById('planner-form');
const results = document.getElementById('results');
const summary = document.getElementById('summary');
const schedule = document.getElementById('schedule');
const message = document.getElementById('message');
const rowCount = document.getElementById('row-count');
const money = new Intl.NumberFormat(undefined, { style: 'currency', currency: 'USD' });

form.addEventListener('submit', (event) => {
  event.preventDefault();
  message.textContent = '';
  const goal = Number(form.elements.goal.value);
  const deposit = Number(form.elements.deposit.value);
  const yearlyRate = Number(form.elements.rate.value);
  if (!Number.isFinite(goal) || goal <= 0 || !Number.isFinite(deposit) || deposit <= 0 || !Number.isFinite(yearlyRate) || yearlyRate < 0) {
    results.hidden = true;
    message.textContent = 'Enter a positive goal and monthly deposit, and a non-negative yearly rate.';
    return;
  }

  const monthlyRate = yearlyRate / 100 / 12;
  let balance = 0;
  let totalInterest = 0;
  const rows = [];
  const maxMonths = 1200;
  for (let month = 1; month <= maxMonths && balance < goal; month += 1) {
    const interest = Math.round(balance * monthlyRate * 100) / 100;
    const contribution = Math.min(deposit, Math.max(0, goal - balance - interest));
    balance = Math.round((balance + interest + contribution) * 100) / 100;
    totalInterest = Math.round((totalInterest + interest) * 100) / 100;
    rows.push({ month, contribution, interest, balance });
  }
  if (balance < goal) {
    results.hidden = true;
    message.textContent = 'This plan does not reach the goal within 100 years. Try a larger monthly deposit.';
    return;
  }

  const months = rows.length;
  const years = Math.floor(months / 12);
  const remainingMonths = months % 12;
  const duration = years ? `${years} yr${years === 1 ? '' : 's'}${remainingMonths ? ` ${remainingMonths} mo` : ''}` : `${months} mo`;
  summary.innerHTML = `<div class="stat"><span class="stat-label">Time to your goal</span><span class="stat-value">${duration}</span></div><div class="stat"><span class="stat-label">Interest earned</span><span class="stat-value">${money.format(totalInterest)}</span></div>`;
  schedule.replaceChildren(...rows.map((row) => {
    const tr = document.createElement('tr');
    if (row.month === months) tr.className = 'goal-row';
    const values = [`Month ${row.month}`, money.format(row.contribution), money.format(row.interest), money.format(row.balance)];
    values.forEach((value) => { const td = document.createElement('td'); td.textContent = value; tr.append(td); });
    return tr;
  }));
  rowCount.textContent = `${months} month${months === 1 ? '' : 's'}`;
  results.hidden = false;
  results.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
});
